import type { NextPage } from "next";
import dynamic from "next/dynamic";
import { useEffect, useState } from "react";

// Dynamically import CountUp and cast to any to work around type issues
const CountUpComponent: any = dynamic(() => import("react-countup"), {
  ssr: false,
});

interface StatItem {
  id: number;
  label: string;
  value: number;
  suffix?: string;
}

const statsData: StatItem[] = [
  {
    id: 1,
    label: "Years of Experience delivering world-class web solutions",
    value: 10,
    suffix: "+",
  },
  {
    id: 2,
    label: "Successful Projects built for global clients",
    value: 250,
    suffix: "+",
  },
  {
    id: 3,
    label: "Advanced Technologies in our stack",
    value: 80,
    suffix: "+",
  },
  {
    id: 4,
    label: "Dedicated Experts with industry-specific knowledge",
    value: 100,
    suffix: "+",
  },
];

const WhyChooseAST: NextPage = () => {
  // Track component mount state to ensure the client renders CountUp only after mounting
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  return (
    <section className="py-16 bg-gray-50">
      <div className="max-w-6xl mx-auto px-4">
        <h2 className="text-3xl md:text-4xl font-bold text-center text-gray-800 mb-12">
          Why Choose AST for Web App Development?
        </h2>
        <div className="grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-4">
          {statsData.map((stat) => (
            <div
              key={stat.id}
              className="bg-white p-8 rounded-xl shadow text-center transform transition-all duration-300 hover:scale-105 hover:shadow-xl"
            >
              <div className="text-5xl font-extrabold text-blue-600 mb-4">
                {mounted ? (
                  <CountUpComponent
                    start={0}
                    end={stat.value}
                    duration={2}
                    suffix={stat.suffix}
                    enableScrollSpy={true}
                    scrollSpyOnce={true}
                  >
                    {({ countUpRef }: any) => <span ref={countUpRef} />}
                  </CountUpComponent>
                ) : (
                  <span>0{stat.suffix}</span>
                )}
              </div>
              <p className="text-gray-600 text-sm leading-relaxed">
                {stat.label}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default WhyChooseAST;
